"""One `<Instance>.xml` AMPS configuration file per instance."""

from dataclasses import dataclass

from topoc.amps.builder import build_configs
from topoc.amps.layout import to_xml
from topoc.catalog import Catalog
from topoc.model import ResolvedSystem
from topoc.xmldoc import write_document


@dataclass(frozen=True, slots=True)
class GeneratedFile:
    """A generated file. `name` is relative to the output directory; the caller
    owns writing it."""

    name: str
    content: str


def generate(system: ResolvedSystem, catalog: Catalog) -> list[GeneratedFile]:
    """The configuration files, in instance declaration order. Pure: performs no
    I/O. Raises `GenerateError` (see `build_configs`)."""
    return [
        GeneratedFile(
            name=f"{config.name}.xml",
            content=write_document(
                to_xml(config), f"{config.name} :: generated by topoc; do not edit by hand"
            ),
        )
        for config in build_configs(system, catalog)
    ]
